 auto&j=*job_;if(h.indent!=j.depth)return false;auto&s=j.service;const auto cost=s.nextClocks(h.lastwrite);const auto begin=h.cycles;const auto previous=h.lastwrite;const auto used=s.advanceBefore(cost,[&](uint32_t raw,unsigned dt){const auto a=raw&0xffffff;if(!endpoint(a))throw std::logic_error("Unsupported evolving global read endpoint");h.cycles=begin+dt;h.lastread=history(a);return h.readResource(a);},[&](uint32_t raw,uint8_t v,unsigned dt){const auto a=raw&0xffffff;if(!endpoint(a))throw std::logic_error("Unsupported evolving global write endpoint");h.cycles=begin+dt;h.lastwrite=history(a);h.writeResource(a,v);},previous);if(!cost||used!=cost)throw std::logic_error("Global phase admission differs");if(s.effect().read)h.lastread=-1;if(s.effect().write)h.lastwrite=-1;components|=s.components();++phases;
 if(s.complete()){CallerAbi a;for(unsigned n=0;n<7;++n)a.values[n]=uint32_t(h.regs[n].er);a.flags=h.ccr;project(a,s);for(unsigned n=0;n<7;++n)h.regs[n].er=int32_t(a.values[n]);h.ccr=a.flags;uint32_t target=0;for(unsigned n=0;n<4;++n){h.cycles=begin+8+3*n;h.lastread=-1;target=(target<<8)|h.readResource(j.caller+n);}h.setSP(j.caller+4);h.pc=target&0xffffff;h.exr=j.priority;--h.indent;job_.reset();++completed;}h.cycles=begin+cost;return true;
